paths.message:
Run processes with `Bun.$` (shell) or `Bun.spawn` (argv).

- import { execFileSync } from "node:child_process";
- const out = execFileSync("git", ["status"]).toString();
+ import { $ } from "bun";
+ const out = await $`git status`.text();

Use `bun:sqlite`.

- import { DatabaseSync } from "node:sqlite";
- const db = new DatabaseSync("app.db");
- const rows = db.prepare("SELECT * FROM users").all();
+ import { Database } from "bun:sqlite";
+ const db = new Database("app.db", { strict: true });
+ const rows = db.query("SELECT * FROM users").all();

Use `bun:test`; `bun test` runs it.

- import { test } from "node:test";
- import assert from "node:assert/strict";
- test("adds", () => assert.equal(1 + 1, 2));
+ import { expect, test } from "bun:test";
+ test("adds", () => expect(1 + 1).toBe(2));

Use `bun:test`; `bun test` runs it.

- import { expect, jest, test } from "@jest/globals";
- const fn = jest.fn();
+ import { expect, mock, test } from "bun:test";
+ const fn = mock();

Hash passwords with `Bun.password` (argon2id by default).

- import argon2 from "argon2";
- const hash = await argon2.hash(password);
- const ok = await argon2.verify(hash, password);
+ const hash = await Bun.password.hash(password, "argon2id");
+ const ok = await Bun.password.verify(password, hash);

Hash passwords with `Bun.password`.

- import bcrypt from "bcrypt";
- const hash = await bcrypt.hash(password, 10);
- const ok = await bcrypt.compare(password, hash);
+ const hash = await Bun.password.hash(password, { algorithm: "bcrypt", cost: 10 });
+ const ok = await Bun.password.verify(password, hash);

Use `bun:sqlite`; it has the same prepare/run/get/all API.

- import Database from "better-sqlite3";
- const db = new Database("app.db");
- const rows = db.prepare("SELECT * FROM users").all();
+ import { Database } from "bun:sqlite";
+ const db = new Database("app.db", { strict: true });
+ const rows = db.query("SELECT * FROM users").all();

Use the global `fetch`.

- import fetch from "cross-fetch";
- const res = await fetch(url);
+ const res = await fetch(url); // global, no import

Use `Bun.spawn`; it is cross-platform.

- import spawn from "cross-spawn";
- spawn("git", ["status"], { stdio: "inherit" });
+ const proc = Bun.spawn(["git", "status"], { stdout: "inherit" });
+ await proc.exited;

Use `Bun.$` (shell) or `Bun.spawn` (argv).

- import { execa } from "execa";
- const { stdout } = await execa("git", ["status"]);
+ import { $ } from "bun";
+ const stdout = await $`git status`.text();

Use `Bun.Glob`.

- import glob from "fast-glob";
- const files = await glob("src/**/*.ts");
+ const files = await Array.fromAsync(new Bun.Glob("src/**/*.ts").scan());

Use `Bun.Glob`.

- import { glob } from "glob";
- const files = await glob("src/**/*.ts");
+ const files = await Array.fromAsync(new Bun.Glob("src/**/*.ts").scan());

Use `bun:test`; `bun test` runs it.

- import { expect, jest, test } from "jest";
- const fn = jest.fn();
+ import { expect, mock, test } from "bun:test";
+ const fn = mock();

Use `Bun.YAML`.

- import yaml from "js-yaml";
- const data = yaml.load(text);
- const out = yaml.dump(data);
+ const data = Bun.YAML.parse(text);
+ const out = Bun.YAML.stringify(data);

Use the global `fetch`.

- import fetch from "node-fetch";
- const res = await fetch(url);
+ const res = await fetch(url); // global, no import

Use `Bun.$`.

- import shell from "shelljs";
- shell.rm("-rf", "dist");
- const out = shell.exec("git status").stdout;
+ import { $ } from "bun";
+ await $`rm -rf dist`;
+ const out = await $`git status`.text();

Use `bun:sqlite`; it is synchronous, no callbacks.

- import sqlite3 from "sqlite3";
- const db = new sqlite3.Database("app.db");
- db.all("SELECT * FROM users", (error, rows) => {});
+ import { Database } from "bun:sqlite";
+ const db = new Database("app.db", { strict: true });
+ const rows = db.query("SELECT * FROM users").all();

Use `crypto.randomUUID` (v4) or `Bun.randomUUIDv7` (v7).

- import { v4, v7 } from "uuid";
- const id = v4();
- const ordered = v7();
+ const id = crypto.randomUUID();
+ const ordered = Bun.randomUUIDv7();

Use `bun:test`; `bun test` runs it.

- import { expect, vi, test } from "vitest";
- const fn = vi.fn();
+ import { expect, mock, test } from "bun:test";
+ const fn = mock();

Use `Bun.$`; it escapes interpolated values the same way.

- import { $ } from "zx";
+ import { $ } from "bun";
  await $`git status`;
